head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > executeWorkflow]<br/>Workflow 의 ID 또는 객체를 사용하여 Workflow 를 실행합니다. 정의된 step 순서에 따라 Submission 과 함수를 실행합니다.",
    "validation" : [
        "workflow(필수) 파라미터를 Workflow 의 ID 문자열 또는 Workflow 정의 객체로 설정할 수 있어야 합니다.",
        "workflow.id(필수) 로 Workflow 의 ID 를 설정할 수 있어야 합니다.",
        "workflow.processMsg(선택) 로 통신 중 표시할 프로세스 메시지를 설정할 수 있어야 합니다. ('$blank' 설정 시 미표시)",
        "workflow.resolveCallback(선택) 로 모든 단계 정상 처리 후 실행할 함수를 설정할 수 있어야 합니다.",
        "workflow.rejectCallback(선택) 로 단계 진행 중 오류 발생 시 실행할 함수를 설정할 수 있어야 합니다.",
        "workflow.step[](필수) 배열에 정의된 순서대로 submit / submitDone / function 단계를 실행해야 합니다.",
        "workflow.step[i].type(필수) 으로 'submit' / 'submitDone' / 'function' 단계 유형을 설정할 수 있어야 합니다.",
        "workflow.step[i].action(필수) 으로 submission ID 또는 함수명/객체를 설정할 수 있어야 합니다.",
        "workflow.step[i].pre(선택) 로 submit 실행 전 호출 함수를 설정할 수 있으며, 반환값이 true 가 아니면 중단되어야 합니다.",
        "workflow.step[i].post(선택) 로 submitDone 응답 후 호출 함수를 설정할 수 있어야 합니다.",
        "workflow.step[i].requestData(선택) 로 submit 에 전달할 요청 데이터를 설정할 수 있어야 합니다.",
        "반환값은 Promise 이며, 정상 완료 시 resolveCallback 이 호출되어야 합니다.",
        "workflow 파라미터를 Object 로 전달하면 임시로 생성되고 완료 후 자동 삭제되어야 합니다.",
        "'submitDone' step 은 반드시 대응하는 'submit' step 이 필요하며, 하나의 'submit' 에 대해 'submitDone' 은 하나만 존재해야 합니다.",
        "Workflow 미정의 또는 동일 ID 가 이미 실행 중이면 Promise.resolve(false) 를 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// workflow step 에서 호출할 function 정의
scwin.wf_function1 = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[step] function - scwin.wf_function1 실행됨");
};

scwin.wf_function2 = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[step] function - scwin.wf_function2 실행됨");
};

// submission pre / post 함수
scwin.sbm_exam1_pre = function (submissionId, workflowObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[pre] scwin.sbm_exam1_pre 호출 (submissionId : '" + submissionId + "') → true 반환");
    return true;
};

scwin.sbm_exam1_post = function (submissionObj, workflowObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[post] scwin.sbm_exam1_post 호출");
};

// submission 이벤트
scwin.sbm_exam1_submit = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[submit] sbm_exam1 실행");
};

scwin.sbm_exam1_submitdone = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[submitDone] sbm_exam1 응답 수신");
};

scwin.sbm_exam1_submiterror = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[submitError] sbm_exam1 오류");
};

scwin.sbm_exam2_submit = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[submit] sbm_exam2 실행");
};

scwin.sbm_exam2_submitdone = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[submitDone] sbm_exam2 응답 수신");
};

scwin.sbm_exam2_submiterror = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[submitError] sbm_exam2 오류");
};

// workflow 전체 콜백
scwin.wf_resolveCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[resolveCallback] workflow 완료");
};

scwin.wf_rejectCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[rejectCallback] workflow 오류");
};



scwin.btn_executeWorkflow_onclick = function () {
    var scenario = par_scenario.getValue();
    var ret;

    if (scenario === "1") {
        // 시나리오 1 : ID 문자열로 실행 (XML 의 workflowCollection 에 정의된 wf_exam1)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : ID 문자열로 executeWorkflow 실행 ──");
        ret = WebSquare.ModelUtil.executeWorkflow("wf_exam1");
    } else if (scenario === "2") {
        // 시나리오 2 : Object 로 실행 (가이드 예시 기반)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : Object 로 executeWorkflow 실행 ──");
        var workflowObj = {
            "id" : "wf_exam_dynamic",
            "processMsg" : "$blank",
            "step" : [
                { "type" : "function", "action" : "scwin.wf_function1" },
                { "type" : "submit",     "action" : "sbm_exam2" },
                { "type" : "submitDone", "action" : "sbm_exam2" },
                { "type" : "function",   "action" : "scwin.wf_function2" }
            ],
            "resolveCallback" : scwin.wf_resolveCallback,
            "rejectCallback"  : scwin.wf_rejectCallback
        };
        ret = WebSquare.ModelUtil.executeWorkflow(workflowObj);
    }

    // Promise 반환 확인
    var retType = (ret && typeof ret.then === "function") ? "Promise" : (typeof ret);
    wf_body_bottom.getObj("scwin").setReturnValue("executeWorkflow 반환값 타입 : " + retType);
};
